    "title": "Char Siu (Chinese BBQ Honey Pork)",
    "cuisineId": "chinese",
    "prepTime": 15,
    "cookTime": 20,
    "servings": 4,
    "calories": 469,
    "description": "Roasted pork shoulder caramelized in a sticky marinade of honey, hoisin sauce, and Chinese five-spice.",
    "culturalNote": "An authentic preparation representing the rich culinary heritage of traditional chinese kitchens.",
    "imageEmoji": "🍖",
    "mealType": [
      "lunch",
      "dinner"
    ],
